"""Lua fixtures for the source-backed GameEvents aggregate-method candidate.

The parent host owns execution. Run CASES in one GameEvents context, then run
CONTEXT_SETUP in two distinct child environments, CONTEXT_DISPATCH in either,
and CONTEXT_VERIFY_AND_CLEANUP in both.
"""
from civ6_host.runtime.provenance import historical_source_file as _historical_source_file, historical_module_file as _historical_module_file, worker_path as _worker_path, pin_key as _pin_key, installed_source_pins as _installed_source_pins
from civ6_host.runtime.resource_resolution import resolve_path as _resolve_resource_path
CASES = b"\nlocal f=GameEvents.Civ6RL_AggregatorFloat\nlocal i=GameEvents.Civ6RL_AggregatorInt\nlocal a=GameEvents.Civ6RL_AggregatorAny\nlocal l=GameEvents.Civ6RL_AggregatorAll\nassert(f.Accumulate()==nil and i.AccumulateINT()==nil)\nassert(a.TestAny()==nil and l.TestAll()==nil)\n\n-- All method arguments pass unchanged to each child listener.\nlocal hits={float=0,int=0,any=0,all=0}\nf.Add(function(n,s) assert(n==41 and s=='x'); hits.float=hits.float+1; return 0.1 end)\nassert(f.Accumulate(41,'x')==0.10000000149011612 and hits.float==1)\nf.RemoveAll()\ni.Add(function(n,s) assert(n==41 and s=='x'); hits.int=hits.int+1; return 1.9 end)\nassert(i.AccumulateINT(41,'x')==1 and hits.int==1)\ni.RemoveAll()\na.Add(function(n,s) assert(n==41 and s=='x'); hits.any=hits.any+1; return true end)\nassert(a.TestAny(41,'x')==true and hits.any==1)\na.RemoveAll()\nl.Add(function(n,s) assert(n==41 and s=='x'); hits.all=hits.all+1; return true end)\nassert(l.TestAll(41,'x')==true and hits.all==1)\nl.RemoveAll()\n\n-- Accumulate narrows each return and the accumulator to float32.\nf.Add(function() return 16777216 end)\nf.Add(function() return 1 end)\nf.Add(function() return -16777216 end)\nassert(f.Accumulate()==0)\nf.RemoveAll()\n\n-- hks_obj_tonumber: numeric strings parse; invalid strings and other tags are 0.\nf.Add(function() return '2.5' end)\nf.Add(function() return 'not numeric' end)\nf.Add(function() return true end)\nf.Add(function() return {} end)\nassert(f.Accumulate()==2.5)\nf.RemoveAll()\n\n-- AccumulateINT truncates each conversion toward zero and adds as int32.\ni.Add(function() return 1.9 end)\ni.Add(function() return -2.9 end)\nassert(i.AccumulateINT()==-1)\ni.RemoveAll()\ni.Add(function() return 2147483647 end)\ni.Add(function() return 1 end)\nassert(i.AccumulateINT()==-2147483648)\ni.RemoveAll()\ni.Add(function() return 2147483648 end)\nassert(i.AccumulateINT()==-2147483648) -- CVTTSD2SI out-of-range result\ni.RemoveAll()\n\n-- Errors are skipped, but a nonempty list still selects its initialized result.\ni.Add(function() error('aggregate error') end)\nassert(i.Accumulate()==0)\ni.RemoveAll()\ni.Add(function() error('aggregate error') end)\nassert(i.AccumulateINT()==0)\ni.RemoveAll()\na.Add(function() error('aggregate error') end)\nassert(a.TestAny()==false)\na.RemoveAll()\nl.Add(function() error('aggregate error') end)\nassert(l.TestAll()==true)\nl.RemoveAll()\n\n-- The loops do not short-circuit after the aggregate value is determined.\nlocal anyTail,allTail=0,0\na.Add(function() return true end)\na.Add(function() anyTail=anyTail+1; return false end)\nassert(a.TestAny()==true and anyTail==1)\na.RemoveAll()\nl.Add(function() return false end)\nl.Add(function() allTail=allTail+1; return true end)\nassert(l.TestAll()==false and allTail==1)\nl.RemoveAll()\nassert(f.Accumulate()==nil and i.AccumulateINT()==nil)\nassert(a.TestAny()==nil and l.TestAll()==nil)\n"
CONTEXT_SETUP = b"\nCiv6RL_AggregatorHits={Accumulate=0,AccumulateINT=0,TestAny=0,TestAll=0}\nlocal marker=Civ6RL_AggregatorMarker\nassert(marker=='first' or marker=='second')\nlocal f=GameEvents.Civ6RL_AggregatorContextFloat\nlocal i=GameEvents.Civ6RL_AggregatorContextInt\nlocal a=GameEvents.Civ6RL_AggregatorContextAny\nlocal l=GameEvents.Civ6RL_AggregatorContextAll\nf.Add(function(x) assert(x==73 and Civ6RL_AggregatorMarker==marker); Civ6RL_AggregatorHits.Accumulate=Civ6RL_AggregatorHits.Accumulate+1; return 1 end)\ni.Add(function(x) assert(x==73 and Civ6RL_AggregatorMarker==marker); Civ6RL_AggregatorHits.AccumulateINT=Civ6RL_AggregatorHits.AccumulateINT+1; return 1 end)\na.Add(function(x) assert(x==73 and Civ6RL_AggregatorMarker==marker); Civ6RL_AggregatorHits.TestAny=Civ6RL_AggregatorHits.TestAny+1; return true end)\nl.Add(function(x) assert(x==73 and Civ6RL_AggregatorMarker==marker); Civ6RL_AggregatorHits.TestAll=Civ6RL_AggregatorHits.TestAll+1; return true end)\n"
CONTEXT_DISPATCH = b'\nassert(GameEvents.Civ6RL_AggregatorContextFloat.Accumulate(73)==2)\nassert(GameEvents.Civ6RL_AggregatorContextInt.AccumulateINT(73)==2)\nassert(GameEvents.Civ6RL_AggregatorContextAny.TestAny(73)==true)\nassert(GameEvents.Civ6RL_AggregatorContextAll.TestAll(73)==true)\n'
CONTEXT_VERIFY_AND_CLEANUP = b'\nassert(Civ6RL_AggregatorHits.Accumulate==1)\nassert(Civ6RL_AggregatorHits.AccumulateINT==1)\nassert(Civ6RL_AggregatorHits.TestAny==1)\nassert(Civ6RL_AggregatorHits.TestAll==1)\nGameEvents.Civ6RL_AggregatorContextFloat.RemoveAll()\nGameEvents.Civ6RL_AggregatorContextInt.RemoveAll()\nGameEvents.Civ6RL_AggregatorContextAny.RemoveAll()\nGameEvents.Civ6RL_AggregatorContextAll.RemoveAll()\n'
